  Summon_117218_Title = {
    Text = "与群星相会"
  },
  Summon_117219_Desc = {
    Text = "限时活动，仅能唤醒<SummonOrange:5>次！"
  },
  Summon_117219_LongDesc1 = {
    Text = "【<SummonOrange:与群星相会·女性>】命轨合契唤醒已开启。开启期间，守密人可从中随机唤醒 1 个星辰篇女性SSR唤醒体、1 个忘却篇女性SSR唤醒体、 1 个星辰篇女性唤醒体推荐SSR命轮、 2个忘却篇女性唤醒体推荐SSR命轮。\n·每个命轨合契唤醒将会在唤醒 5 次后关闭。\n·本次命轨合契唤醒活动中，每次唤醒都将必定获得随机SSR唤醒体 或 随机SSR命轮。\n\n<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。"
  },
  Summon_117219_LongDesc2 = {
    Text = "<Title:【SSR物品】>\n在【<SummonOrange:与群星相会·女性>】命轨合契唤醒中，获取SSR物品的综合概率为100.00%。获取的SSR物品为 2 个唤醒体和 3 个命轮。\n·通过唤醒获取到SSR唤醒体时，有100%的概率为<SummonOrange:女性>的唤醒体。\n\n<Title:【特殊说明】>\n·无论通过何种方式（包括但不限于唤醒、商店兑换、系统赠送等）第 2~16 次获得相同SSR唤醒体时，每次将转换为 1 个对应唤醒体的残片和 50 个根源沉淀；第 17 次及之后获得，非限定SSR唤醒体将转换为「灵魂回溯碎片」× 1 和 「根源沉淀」× 150，限定SSR唤醒体将转换为「灵魂回溯碎片」× 2 和「根源沉淀」× 250 。但通过任选方式（包括原质乐园、灵魂回溯之芯、原型视界等）以及随机方式（包括原质捕获·忘却篇等）获得唤醒体或溢出唤醒体残片时，不会转换根源沉淀。"
  },
