  Summon_130227_LongDesc1 = {
    Text = "【<SummonRed:爱与死之芽>】限时角色活动唤醒已开启。活动期间，守密人可从中唤醒限时活动UP角色<SummonRed:沙耶>。\n·活动期间，限定SSR唤醒体<SummonRed:沙耶>的唤醒获得概率将发生提升。\n·本次限时活动唤醒中，除触发概率提升、保底等特殊规则外，所有唤醒体或命轮均使用基础概率，具体以规则说明为准。\n·每日推荐唤醒：本次限时活动唤醒中，守密人每日能以60源液的优惠唤醒一次，并额外赠送60银芯。\n\n<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。\n\n<Title:【特殊说明】>\n·<SummonRed:沙耶>为「沙耶之歌」特别联动唤醒体（<SummonRed:愿世界化作芬芳>为「沙耶之歌」联动命轮），在首次推出后拥有较长的授权期，授权期间可能多次复刻并且能够通过其他方式获取。授权期临满且因为各种原因确实无法继续保持授权时，会提前进行预告。\n\n"
  },
