  },
  Summon_138790_LongDesc1 = {
    Text = "【<SummonOrange:群星的盛绽·伤害型>】命轨合契·三倍唤醒已开启。开启期间，守密人可从中随机唤醒 6 个伤害型SSR唤醒体、 9 个伤害型唤醒体推荐SSR命轮。\n·每个命轨合契·三倍唤醒将会在唤醒 5 次后关闭。\n·本次命轨合契·三倍唤醒活动中，每次唤醒都将必定获得随机SSR唤醒体 或 随机SSR命轮。\n\n<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。"
  },
