  Summon_14135_LongDesc1 = {
    Text = "【轮转之相】为常驻命轮唤醒，守密人可从中获取命轮。\n·在【轮转之相】常驻命轮唤醒中，需要先选择SSR命轮为定向命轮后才可以进行唤醒。定向命轮的唤醒获得概率将大幅提升！\n·在【轮转之相】常驻命轮唤醒中，每5次唤醒必会获得至少1个SR或以上品质命轮。\n·在【轮转之相】常驻命轮唤醒中，除触发概率提升、保底等特殊规则外，所有唤醒体或命轮均使用基础概率，具体以规则说明为准。\n\n<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。\n"
  },
  Summon_14135_LongDesc2 = {
    Text = "<Title:【SSR物品】>\n·在【轮转之相】常驻命轮唤醒中，获取SSR物品的基础概率为 3.03%，综合概率（含保底）为 5.02%。 \n·获取的SSR物品均为命轮，最多 30 次唤醒必定能通过保底获取SSR命轮。\n·通过唤醒获取到SSR命轮时，有33.33%的概率为当前定向命轮。\n·若连续2次唤醒获取的SSR命轮非定向命轮，则下次通过唤醒获取的SSR命轮必定为当前定向命轮。\n·当前已连续 {s1} 次获得非定向命轮。\n·以下忘却篇限定命轮已加入「轮转之相」常驻唤醒，并在「轮转之相」常驻唤醒中共同分摊 0.5% 的 SSR 命轮综合出现概率，这些限定命轮仍然无法定向选择，也无法通过「轮转之书」获取。\n ○ 命轮「神王的颂歌」「跨越疼痛」「以蔷薇之名」「至为珍贵的藏品」「隐秘的诞生」「女王的戒律」「神言石板」「畸体回噬」「慈悲的哺育」「虔诚的伟力」「诗笺的句尾」「好运时间」「永恒安魂曲」「沉入殷红」「隐世的转轮」已加入「轮转之相」常驻唤醒。\n\n<Title:【SR物品】>\n·在【轮转之相】常驻命轮唤醒中，获取SR物品的基础概率为 15.85%，综合概率（含保底）为 25.00%。本唤醒内的SR物品均为命轮。\n·最多 5 次唤醒必定能通过保底获得SR或以上物品，通过保底获得SR物品的概率为 96.97%，获得SSR物品的概率为 3.03%。\n\n<Title:【特殊说明】>\n·唤醒获得SSR命轮时，会同时获得 50 个根源沉淀作为副产物；获得SR命轮时，会同时获得 5 个根源沉淀作为副产物；获得R命轮时，会同时获得 1 个根源沉淀作为副产物。\n·无论通过何种方式（包括但不限于唤醒、商店兑换、系统赠送等）第 2~16 次获得相同SSR命轮时，每次将自动提升叠位等级和获得 「 根源沉淀」× 50；第 17 次及之后获得，将转换为「命途回溯碎片」× 1、「 根源沉淀」× 50、「蔷薇金券」× 20000，限定SSR命轮将转化为「命途回溯碎片」× 2、「 根源沉淀」× 50、「蔷薇金券」× 20000。但通过任选方式（包括轮转之书、命途回溯之芯等）以及随机方式（包括宿命定格·忘却篇等）获得命轮时，不会转换根源沉淀。\n·本次唤醒属于【常驻命轮唤醒】，保底唤醒次数将单独累计，且与其他唤醒类型的保底唤醒次数独立统计。\n"
