  Summon_14142_Desc = {
    Text = "每<SummonRed:5>次唤醒必出SR级或以上对象"
  },
  Summon_14142_LongDesc1 = {
    Text = "【界域研习】为常驻角色唤醒，守密人可随时修改指定界域，获取不同界域的唤醒体。当前指定为【<SummonRed:血肉>】界域。\n·在【界域研习】常驻角色唤醒指定界域后，可通过唤醒获取唤醒体及命轮，若获得唤醒体，则必定是指定界域的唤醒体。\n·在【界域研习】常驻角色唤醒中，除触发概率提升、保底等特殊规则外，所有唤醒体或命轮均使用基础概率，具体以规则说明为准。\n\n·<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。\n"
  },
  Summon_14142_LongDesc2 = {
    Text = "<Title:【SSR物品】>\n·在【界域研习】常驻角色唤醒中，获取SSR物品的基础概率为 3.03%，综合概率（含保底）为 5.02%。获取的SSR物品均为唤醒体，最多 30 次唤醒必定能通过保底获取SSR唤醒体。\n·以下忘却篇限定唤醒体已加入「界域研习」常驻唤醒，并在各自界域的「界域研习」常驻唤醒中共同分摊 0.5% 的 SSR 唤醒体综合出率，这些限定唤醒体仍然无法通过「原质乐园」获取。\n ·<SummonOrange:「混沌」>界域：「莉莉」「24」「莱克」「哈姆林」「塔薇」\n ·<SummonBlue:「深海」>界域：「图鲁」「墨菲」「弥利亚姆」\n ·<SummonRed:「血肉」>界域：「索蕾尔」「萨尔瓦多」「泰旖丝」「血链·希洛」\n ·<SummonPurple:「超维」>界域：「达芙黛尔」「旺达」「奥尔拉」\n\n<Title:【SR物品】>\n·在【界域研习】常驻角色唤醒中，获取SR物品的基础概率为 15.85%，综合概率（含保底）为 25.00%。本唤醒内的SR物品均为命轮。\n·最多 5 次唤醒必定能通过保底获得SR或以上物品，通过保底获得SR物品的概率为 96.97%，获得SSR物品的概率为 3.03%。\n\n<Title:【特殊说明】>\n·唤醒获得SR命轮时，会同时获得 5 个根源沉淀作为副产物；获得R命轮时，会同时获得 1 个根源沉淀作为副产物。\n·无论通过何种方式（包括但不限于唤醒、商店兑换、系统赠送等）第 2~16 次获得相同SSR唤醒体时，每次将转换为 1 个对应唤醒体的残片和 50 个根源沉淀；第 17 次及之后获得，非限定SSR唤醒体将转换为「灵魂回溯碎片」× 1 和 「根源沉淀」× 150，限定SSR唤醒体将转换为「灵魂回溯碎片」× 2 和「根源沉淀」× 250 。但通过任选方式（包括原质乐园、灵魂回溯之芯、原型视界等）以及随机方式（包括原质捕获·忘却篇等）获得唤醒体或溢出唤醒体残片时，不会转换根源沉淀。\n·本次唤醒属于【常驻角色唤醒】，保底唤醒次数将单独累计，且与其他唤醒类型的保底唤醒次数独立统计。\n\n"
  },
