  Summon_148077_Title = {
    Text = "糖霜蜜语"
  },
  Summon_149326_Desc = {
    Text = "每<SummonOrange:30>次唤醒必出以上对象！"
  },
  Summon_149326_LongDesc1 = {
    Text = "【<SummonOrange:觅星于怀>】百相自选唤醒限时唤醒已开启。活动期间，守密人可从中<SummonOrange:自由选定>指定数量的唤醒体，被选中的唤醒体及其推荐命轮将作为本次唤醒活动的SSR名单。\n\n·活动期间，每次获得的SSR必定为选定的唤醒体或命轮。\n·本次百相自选唤醒限时唤醒中，除触发概率提升、保底等特殊规则外，所有唤醒体或命轮均使用基础概率，具体以规则说明为准。\n·每日推荐唤醒：本次限时活动唤醒中，守密人每日能以60源液的优惠唤醒一次，并额外赠送60银芯。\n\n<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。\n\n"
  },
  Summon_149326_LongDesc2 = {
    Text = "<Title:【SSR物品】>\n·在【<SummonOrange:觅星于怀>】百相自选唤醒限时唤醒中，获取SSR物品的基础概率为 3.03%，综合概率（含保底）为 5.02%。每 30 次唤醒必定能通过保底获取所选定的SSR唤醒体或SSR命轮。\n·通过唤醒获取到SSR时，有33.33%的概率为本期选定的SSR<SummonOrange:唤醒体>。\n·若连续2次唤醒获取到的SSR为命轮，则下次通过唤醒获取的SSR必定为唤醒体。\n·若连续2次唤醒获取到的SSR为唤醒体，则下次通过唤醒获取的SSR必定为命轮。\n·当前已连续 {s1} 次获得SSR唤醒体。\n·当前已连续 {s2} 次获得SSR命轮。\n\n<Title:【SR物品】>\n·在【<SummonOrange:觅星于怀>】活动唤醒中，获取SR物品的基础概率为 15.85%，综合概率（含保底）为 25.00%。本唤醒内的SR物品均为命轮。\n·最多 5 次唤醒必定能通过保底获得SR或以上物品，通过保底获得SR物品的概率为 96.97%，获得SSR物品的概率为 3.03%。\n\n<Title:【特殊说明】>\n·唤醒获得SSR命轮时，会同时获得 50 个根源沉淀作为副产物；唤醒获得SR命轮时，会同时获得 5 个根源沉淀作为副产物；获得R命轮时，会同时获得 1 个根源沉淀作为副产物。\n·无论通过何种方式（包括但不限于唤醒、商店兑换、系统赠送等）第 2~16 次获得相同SSR命轮时，每次将自动提升叠位等级和获得 「 根源沉淀」×50；第 17 次及之后获得，限定SSR命轮将转化为「命途回溯碎片」× 2、「 根源沉淀」× 50、「蔷薇金券」× 20000，第 2~16 次获得相同SSR唤醒体时，每次将转换为 1 个对应唤醒体的残片和 50 个根源沉淀；第 17 次及之后获得，限定SSR唤醒体将转换为「灵魂回溯碎片」× 2 和「根源沉淀」× 250 。但通过任选方式（包括原质乐园、灵魂回溯之芯、原型视界等）以及随机方式（包括原质捕获·忘却篇等）获得唤醒体或溢出唤醒体残片时，不会转换根源沉淀。\n·本次唤醒属于【百相自选唤醒】，在任意【百相自选唤醒】中，保底唤醒次数将共同累计，且与其他唤醒类型的保底唤醒次数独立统计。\n\n"
  },
