  Summon_81451_LongDesc1 = {
    Text = "【银辉初耀】为新手角色唤醒，守密人可进行无限次唤醒，直到获取想要的唤醒体。\n·在【银辉初耀】新手角色唤醒中，每位守密人直到确认唤醒结果前都有无限次免费重新唤醒的机会，每 5 次唤醒必定随机获得一个常驻SSR唤醒体。\n·确认唤醒结果后【银辉初耀】卡池将会关闭。\n·本次新手角色唤醒中，所有命轮均使用基础概率，具体以规则说明为准。\n\n·<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。\n"
