  Summon_81536_Desc = {
    Text = "限时活动，仅能唤醒<SummonBlue:5>次！"
  },
  Summon_81536_LongDesc1 = {
    Text = "【<SummonBlue:未被忘却的·深海>】命轨合契唤醒已开启。活动期间，守密人可从中唤醒 2 个随机SSR唤醒体和 3 个随机SSR命轮。\n·每个命轨合契唤醒将会在唤醒5次后关闭。\n·本次命轨合契唤醒活动中，每次唤醒都将必定获得随机SSR唤醒体 和 随机SSR命轮。\n\n<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。\n\n<Title:【限时任务】>\n·活动期间，首次完成命轨合契唤醒即可完成限时任务，获得「简易幻衣绘形券（一期）」*1！\n·在5 月 26 日 9:00 - 6 月 9 日 9:00（GMT+8）期间，可以在「商店：幻衣订购」使用「简易幻衣绘形券（一期）」兑换简约幻衣。\n·更多获取「简易幻衣绘形券（一期）」的方式可在社区和公告中了解。\n\n"
  },
  Summon_81536_LongDesc2 = {
    Text = "<Title:【SSR物品】>\n在【<SummonBlue:未被忘却的·深海>】命轨合契唤醒中，获取SSR物品的综合概率为100.00%。获取的SSR物品为 2 个唤醒体和 3 个命轮。\n·通过唤醒获取到SSR唤醒体时，有100%的概率为<SummonBlue:深海>界域的唤醒体。\n\n<Title:【特殊说明】>\n·无论通过何种方式（包括但不限于唤醒、商店兑换、系统赠送等）第 2~16 次获得相同SSR唤醒体时，每次将转换为 1 个对应唤醒体的残片和 50 个根源沉淀；第 17 次及之后获得，非限定SSR唤醒体将转换为「灵魂回溯碎片」× 1 和 「根源沉淀」× 150，限定SSR唤醒体将转换为「灵魂回溯碎片」× 2 和「根源沉淀」× 250 。但通过任选方式（包括原质乐园、灵魂回溯之芯、原型视界等）以及随机方式（包括原质捕获·忘却篇等）获得唤醒体或溢出唤醒体残片时，不会转换根源沉淀。"
