  Summon_98328_LongDesc1 = {
    Text = "【<SummonOrange:万律奏鸣>】限时角色活动唤醒已开启。活动期间，守密人可从中唤醒限时活动UP角色<SummonOrange:哈姆林>。\n·活动期间，限定SSR唤醒体<SummonOrange:哈姆林>的唤醒获得概率将发生提升。\n·活动结束后，限定SSR唤醒体<SummonOrange:哈姆林>仍会在首次UP后 3 到 9 个月的限时角色活动唤醒中出现，直到约一年后进入【界域研习】常驻角色唤醒。\n·本次限时活动唤醒中，除触发概率提升、保底等特殊规则外，所有唤醒体或命轮均使用基础概率，具体以规则说明为准。\n\n<Title:【平衡性调整】>\n·由于游戏玩法特殊，出于确保游戏乐趣与公平性角度，游戏可能会对唤醒体、命轮中的效果进行削弱或增强的平衡性调整。\n·当发生削弱时，游戏会开启限时回溯功能来让唤醒体、命轮的养成或唤醒拥有重新部署资源的机会。\n·请务必在知晓和接受这一点的前提下，进行资源投入。\n\n"
  },
